-- Extend the partner referral reward to eligible bookings generated by any referred
-- partner role, not only bookings with a closing_agent_id. The role is identified
-- from booking attribution and the associated listing; partner role does not limit
-- eligibility to earn or refer.
create or replace function public.apply_network_partner_referral_reward()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  listing_row public.properties%rowtype;
  booking_row public.bookings%rowtype;
  generating_partner_id uuid;
  ref_row public.partner_referrals%rowtype;
  owner_base integer;
  reward integer;
begin
  select * into booking_row from public.bookings where id = new.id;
  if not found then
    return new;
  end if;

  select * into listing_row from public.properties where id = booking_row.property_id;
  if not found then
    return new;
  end if;

  -- Keep the existing closing-agent attribution first. If no eligible referred
  -- partner is the closing agent, use the authorised manager or property
  -- introducer associated with the listing. These are attribution roles, not
  -- eligibility gates: all approved partner roles can refer and earn.
  generating_partner_id := booking_row.closing_agent_id;

  if generating_partner_id is null then
    generating_partner_id := listing_row.authorised_manager_id;
  end if;

  if generating_partner_id is null then
    generating_partner_id := listing_row.property_introducer_id;
  end if;

  -- Where the listing schema stores an owner identity, recognise common owner
  -- column names without assuming every deployment has the same optional field.
  if generating_partner_id is null then
    select candidate.id into generating_partner_id
    from (
      select nullif(to_jsonb(listing_row) ->> 'owner_id', '') as id
      union all select nullif(to_jsonb(listing_row) ->> 'owner_user_id', '')
      union all select nullif(to_jsonb(listing_row) ->> 'created_by', '')
      union all select nullif(to_jsonb(listing_row) ->> 'submitted_by', '')
    ) candidates
    where candidates.id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    limit 1;
  end if;

  if generating_partner_id is null or generating_partner_id = booking_row.guest_id then
    return new;
  end if;

  select pr.* into ref_row
  from public.partner_referrals pr
  join public.profiles referred on referred.id = pr.referred_partner_id
  join public.profiles referrer on referrer.id = pr.referrer_partner_id
  where pr.referred_partner_id = generating_partner_id
    and pr.referrer_partner_id <> generating_partner_id
    and referred.role in ('partner', 'admin')
    and referred.account_status = 'active'
    and referrer.role in ('partner', 'admin')
    and referrer.account_status = 'active'
    and pr.status = 'active'
    and pr.eligibility_starts_at is not null
    and pr.eligibility_starts_at <= now()
    and pr.eligibility_ends_at is not null
    and pr.eligibility_ends_at > now()
  order by pr.activated_at desc nulls last
  limit 1;

  if not found then
    return new;
  end if;

  owner_base := coalesce(booking_row.owner_listed_price_ngn, booking_row.accommodation_subtotal, 0);
  reward := public.multiply_ngn_bps(owner_base, 250); -- 2.5%

  update public.bookings
  set direct_referrer_id = ref_row.referrer_partner_id,
      direct_referrer_reward_ngn = reward,
      hamlet_allocation_ngn = greatest(
        0,
        coalesce(hamlet_allocation_ngn, 0)
        + coalesce(direct_referrer_reward_ngn, 0)
        - reward
      )
  where id = booking_row.id
    and coalesce(direct_referrer_reward_ngn, 0) <> reward;

  return new;
end;
$$;

drop trigger if exists apply_network_partner_referral_reward on public.bookings;
create trigger apply_network_partner_referral_reward
  after insert on public.bookings
  for each row execute function public.apply_network_partner_referral_reward();

revoke all on function public.apply_network_partner_referral_reward() from public, anon;
grant execute on function public.apply_network_partner_referral_reward() to service_role;

